;,&quot;name&quot;:&quot;cta:global-footer:social:x-formally-twitter&quot;,&quot;type&quot;:&quot;exit&quot;,&quot;URL&quot;:&quot;https://x.com/" class="group inline-flex items-center no-underline custom-focus primary link-md cursor-pointer text-action-color-secondary-on-dark gap-0 p-0 xdm-wrapped"><span class="inline-flex group-hover:text-action-text-link-primary"><i class="icon-twitter flex justify-center items-center icon-lg  fill-current transition-colors" aria-hidden="true" style="font-size: 32px; width: 32px; height: 32px; color: currentcolor;"><span class="path1"></span><span class="path2"></span><span class="path3"></span><span class="path4"></span><span class="path5"></span><span class="path6"></span><span class="path7"></span><span class="path8"></span><span class="path9"></span><span class="path10"></span><span class="path11"></span><span class="path12"></span><span class="path13"></span><span class="path14"></span></i></span><span title="" class="relative inline-block text-inherit link-text after:content-[&quot;&quot;] after:absolute after:left-0 after:bottom-0 after:h-0.5 after:w-full after:bg-current after:origin-left after:scale-x-0 after:transition-transform after:duration-[0.3s] after:ease-out group-hover:after:scale-x-100 group-hover:text-action-text-link-primary"><span class="sr-only">X (formally Twitter)</span></span></a></li><li class="list-none flex items-center"><a href="https://www.facebook.com/" id="global-footer-facebook" data-qa-id="GlobalCheckoutFooter-FooterSocialLinks-facebook-link" target="_blank" rel="noopener noreferrer" data-tracking="{&quot;eventType&quot;:&quot;web.webinteraction.linkClicks&quot;,&quot;name&quot;:&quot;cta:global-footer:social:facebook&quot;,&quot;type&quot;:&quot;exit&quot;,&quot;URL&quot;:&quot;https://www.facebook.com/" class="group inline-flex items-center no-underline custom-focus primary link-md cursor-pointer text-action-color-secondary-on-dark gap-0 p-0 xdm-wrapped"><span class="inline-flex group-hover:te